function drawCircles(x,y,mySize)
{
	//stroke(0);
	noStroke();
	let dir = random([-1,1]);
	let rphase = random(0,2*PI);
	let freq = random(0.01,0.025);
	let col1 = color(generateColor());
	fill(col1);
	let temp;
	let d = 1;
	if (d < 10)
	{
	  temp = (frameCount * speedMult);
	}else
	{
		temp = 1;
	}
	let xx = x + mySize/2*cos(dir*freq*temp + rphase);
	let yy = y + mySize/2*sin(dir*freq*temp + rphase);
	//strokeWeight(1);
	stroke(0);
	strokeWeight(1);
	line(x,y,xx,yy);
	noStroke();
	circle(xx,yy,mySize/9);
	let col2 = color(generateColor());
	col2.setAlpha(random(100,100));
	fill(col2);
	circle(x,y,mySize/4);
	fill(100);
	circle(xx,yy,mySize/25 + 0*sin(0.01*(frameCount * speedMult)));
}

